contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take amounts of base and quote to transfer into the vault before calling buyShares.
    // The test will transfer tokens by calling the public token contracts through the already-deployed C's _BASE_TOKEN_ and _QUOTE_TOKEN_
    // However, per constraints we may only call c's public surface. So we will rely on externally-visible balances by sending tokens
    // to c via its payable interface is not available; instead we simulate by assuming caller already has tokens and uses c.buyShares.
    // To keep the test self-contained and only use c's public surface, we simply call buyShares and observe shares and totalSupply changes.

    function run(address to) public payable {
        require(to != address(0), "to cannot be zero");

        // Read pre-state
        uint256 beforeShares = c.balanceOf(to);
        (, , uint256 beforeQuoteInput) = (uint256(0), uint256(0), uint256(0));
        uint256 beforeTotalSupply = c.totalSupply();

        // Try to call buyShares; it may revert if no base input or other conditions.
        bool reverted;
        uint256 sharesReturned;
        try c.buyShares(to) returns (uint256 shares, uint256 baseInput, uint256 quoteInput) {
            reverted = false;
            sharesReturned = shares;
        } catch {
            reverted = true;
            sharesReturned = 0;
        }

        // Read post-state (only via public getters)
        uint256 afterShares = c.balanceOf(to);
        uint256 afterTotalSupply = c.totalSupply();

        // General rule:
        // If buyShares did not revert then exactly `sharesReturned` were added to `to`'s balance
        // and totalSupply increased by `sharesReturned`.
        // We express as: not reverted -> (afterShares == beforeShares + sharesReturned && afterTotalSupply == beforeTotalSupply + sharesReturned)
        assert(reverted || (afterShares == beforeShares + sharesReturned && afterTotalSupply == beforeTotalSupply + sharesReturned));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    function run(address to) public payable {
        require(to != address(0));

        // Observe totalSupply before
        uint256 totalBefore = c.totalSupply();

        // Call buyShares and capture returned values and whether it reverted
        bool reverted;
        uint256 shares;
        uint256 baseInput;
        uint256 quoteInput;
        try c.buyShares(to) returns (uint256 _shares, uint256 _baseInput, uint256 _quoteInput) {
            reverted = false;
            shares = _shares;
            baseInput = _baseInput;
            quoteInput = _quoteInput;
        } catch {
            reverted = true;
            shares = 0;
            baseInput = 0;
            quoteInput = 0;
        }

        // Observe totalSupply after
        uint256 totalAfter = c.totalSupply();

        // If the call succeeded (did not revert), then totalAfter == totalBefore + shares.
        // If it reverted, nothing else to assert about state (we only assert the general rule holds when the call succeeded).
        assert(reverted || totalAfter == totalBefore + shares);
    }

    receive() external payable {}
}
